import Foundation
import QuickrCore
import QuickrData
import QuickrTestSupport
import Testing

/// The run DTOs map to QuickrCore's run models (timers.md §2.3, §4.3), and the Swift fold agrees
/// with the state the real server recorded in `shared/fixtures/api/` (generated by
/// backend/tests/test_api_fixtures.py).
@Suite struct RunMappingTests {
    static func decode<R: WireResponse>(_ type: R.Type, _ data: Data) throws -> R.Domain {
        try R.decode(data, using: WireCoding.decoder()).toDomain()
    }

    static func result(_ name: String) throws -> RunEventResult {
        try decode(RunEventResultDTO.self, try #require(try Fixtures.api(name).body))
    }

    /// Every recorded run, by fixture name.
    static func recordedRuns() throws -> [(String, Run)] {
        var out: [(String, Run)] = []
        for fixture in try Fixtures.allAPI() where fixture.isSuccess {
            let body = fixture.body ?? Data("null".utf8)
            switch fixture.operationId {
            case "getRun": out.append((fixture.name, try decode(RunDTO.self, body)))
            case "listRuns": out += try decode([RunDTO].self, body).map { (fixture.name, $0) }
            case "recordRunEvent": out.append((fixture.name, try decode(RunEventResultDTO.self, body).run))
            default: continue
            }
        }
        return out
    }

    /// The steps of the fixtures' topic versions: listTopicVersions (the "everything" topic), and
    /// the step-less "Dishwasher" (test_api_fixtures.py `runs`).
    static func steps(of run: Run) throws -> [TopicTimer.Step] {
        let versions = try decode([TopicVersionDTO].self, try #require(try Fixtures.api("listTopicVersions").body))
        if let version = versions.first(where: { $0.version == run.version }), let timer = version.timer,
            run.topicId == UUID(uuidString: "00000000-0000-4000-8000-000000000001")
        {
            return timer.steps
        }
        return []
    }

    @Test func everyRecordedRunRefoldsToItsRecordedState() throws {
        let runs = try Self.recordedRuns()
        #expect(runs.count >= 10)
        for (name, run) in runs {
            // The server decides a finishing run's discard outside the fold (§3.7).
            guard run.status != .discarded else { continue }
            let state = try RunFold.fold(
                runId: run.id.uuidString, steps: try Self.steps(of: run), events: run.foldEvents)
            var recorded = run.state
            if recorded.status == .finishing { recorded.status = .stopped }  // the fold says stopped (§3.5)
            // The server adds `finish` effects, which it decides outside the fold (§3.6).
            for stored in run.events where stored.event.type == .finish {
                recorded.effects[stored.event.id.lowercased()] = nil
            }
            #expect(state == recorded, "\(name)")
            for stored in run.events where stored.event.type != .finish {
                #expect(state.effects[stored.event.id.lowercased()] == stored.effect, "\(name) \(stored.event.id)")
            }
        }
    }

    @Test func aStoppedRunsEntryCarriesItsTiming() throws {
        for name in ["recordRunEvent.stop", "recordRunEvent.finish", "recordRunEvent.finish_stopped"] {
            let result = try Self.result(name)
            let entry = try #require(result.entry, "\(name)")
            let timing = try #require(entry.timing, "\(name)")
            #expect(RunInstant.milliseconds(entry.capturedAt) == timing.endedAt, "\(name): T1")
            #expect(timing.segments.reduce(0) { $0 + $1.activeMs } == timing.activeMs, "\(name): T5")
            #expect(timing.segments.reduce(0) { $0 + $1.pausedMs } == timing.pausedMs, "\(name): T5")
            #expect(timing == (try RunFold.projectTiming(result.run.state, steps: try Self.steps(of: result.run))))
            #expect(result.effect == .applied)
        }
    }

    @Test func effectsMapAppliedAndVoid() throws {
        let merged = try Self.result("recordRunEvent.merged")
        #expect(merged.effect == .void(.merged))
        #expect(merged.run.aliases.map(\.uuidString.localizedLowercase) == [merged.eventId])
        let void = try Self.result("recordRunEvent.void")
        #expect(void.effect == .void(.stale))
    }

    /// A response that decodes but breaks the run contract fails the mapping, never defaults.
    @Test(arguments: [
        ("/run/status", "\"walking\""),
        ("/run/started_at", "\"2026-03-04 11:00:00\""),
        ("/run/events/0/type", "\"jump\""),
        ("/run/events/0/reason", "\"stale\""),
        ("/run/state/effects/0a000000-0000-4000-8000-000000000001/reason", "\"nope\""),
        ("/run/state/segments/0/kind", "\"lap\""),
        ("/event/effect", "\"void\""),
    ])
    func contractViolationsFailTheMapping(path: String, value: String) throws {
        let body = try #require(try Fixtures.api("recordRunEvent.next").body)
        var object = try #require(try JSONSerialization.jsonObject(with: body) as? [String: Any])
        object = Self.setting(object, path: path.split(separator: "/").map(String.init), to: value)
        let data = try JSONSerialization.data(withJSONObject: object)
        #expect(throws: (any Error).self, "\(path)") { try Self.decode(RunEventResultDTO.self, data) }
    }

    static func setting(_ object: [String: Any], path: [String], to json: String) -> [String: Any] {
        var copy = object
        let key = path[0]
        if path.count == 1 {
            copy[key] = try! JSONSerialization.jsonObject(with: Data(json.utf8), options: .fragmentsAllowed)
        } else if let child = object[key] as? [String: Any] {
            copy[key] = setting(child, path: Array(path.dropFirst()), to: json)
        } else if var array = object[key] as? [[String: Any]], let index = Int(path[1]) {
            array[index] = setting(array[index], path: Array(path.dropFirst(2)), to: json)
            copy[key] = array
        }
        return copy
    }
}
